// Differential checks of Specialize01-faithful.js against Lean, generated by leanscript --check
import * as M from "./Specialize01-faithful.js";

function show(v) {
  if (Array.isArray(v) || ArrayBuffer.isView(v)) return "#[" + [...v].map(show).join(", ") + "]";
  // a list of cons cells (`ListRepr.taggedUnion`) is shown as its elements
  if (v !== null && typeof v === "object" && (v.tag === 0 || v.tag === 1)) {
    const a = [];
    for (; v.tag === 1; v = v._2) a.push(v._1);
    return show(a);
  }
  // a record (a structure-like type) is shown as its fields: `{a, b}`
  if (v !== null && typeof v === "object" && !("tag" in v) && "_1" in v) {
    const fs = [];
    for (let i = 1; ("_" + i) in v; i++) fs.push(show(v["_" + i]));
    return "{" + fs.join(", ") + "}";
  }
  return String(v);
}
// a union `{ tag: i, _1: …, … }` of leaf fields is shown as `i(…, …)`
function showUnion(v) {
  const fs = [];
  for (let i = 1; ("_" + i) in v; i++) fs.push(show(v["_" + i]));
  return v.tag + "(" + fs.join(", ") + ")";
}
function floatBits(x) {
  return String(new BigUint64Array(new Float64Array([x]).buffer)[0]);
}
function isNaNBits(s) {
  const b = BigInt(s);
  return ((b >> 52n) & 0x7ffn) === 0x7ffn && (b & 0xfffffffffffffn) !== 0n;
}
let passed = 0, failed = 0;
function check(label, thunk, expected, isFloat) {
  let got;
  try {
    const v = thunk();
    got = isFloat ? floatBits(v) : show(v);
    // NaN payloads differ between platforms: any NaN matches any NaN
    if (isFloat && Number.isNaN(v) && isNaNBits(expected)) got = expected;
  } catch (e) {
    got = "threw: " + e.message;
  }
  if (got === expected) passed++;
  else {
    failed++;
    console.log(`FAIL ${label}: expected ${JSON.stringify(expected)}, got ${JSON.stringify(got)}`);
  }
}

check("test1(0n)", () => M.test1(0n), "count (0)", false);
check("test1(1n)", () => M.test1(1n), "count (1)", false);
check("test1(2n)", () => M.test1(2n), "count (2)", false);
check("test1(5n)", () => M.test1(5n), "count (5)", false);
check("test1(13n)", () => M.test1(13n), "count (13)", false);
check("test2(0n, \"\")", () => M.test2(0n, ""), "count (0, )", false);
check("test2(1n, \"\")", () => M.test2(1n, ""), "count (1, )", false);
check("test2(0n, \"hello world\")", () => M.test2(0n, "hello world"), "count (0, hello world)", false);
check("test2(2n, \"\")", () => M.test2(2n, ""), "count (2, )", false);
check("test2(1n, \"hello world\")", () => M.test2(1n, "hello world"), "count (1, hello world)", false);
check("test2(5n, \"\")", () => M.test2(5n, ""), "count (5, )", false);
check("test2(0n, \"abcabc\")", () => M.test2(0n, "abcabc"), "count (0, abcabc)", false);
check("test2(2n, \"hello world\")", () => M.test2(2n, "hello world"), "count (2, hello world)", false);
check("test2(13n, \"\")", () => M.test2(13n, ""), "count (13, )", false);
check("test2(1n, \"abcabc\")", () => M.test2(1n, "abcabc"), "count (1, abcabc)", false);
check("test2(5n, \"hello world\")", () => M.test2(5n, "hello world"), "count (5, hello world)", false);
check("test2(2n, \"abcabc\")", () => M.test2(2n, "abcabc"), "count (2, abcabc)", false);
check("test2(13n, \"hello world\")", () => M.test2(13n, "hello world"), "count (13, hello world)", false);
check("test2(5n, \"abcabc\")", () => M.test2(5n, "abcabc"), "count (5, abcabc)", false);
check("test2(13n, \"abcabc\")", () => M.test2(13n, "abcabc"), "count (13, abcabc)", false);
check("test3(\"\", 0n)", () => M.test3("", 0n), " (0)", false);
check("test3(\"\", 2n)", () => M.test3("", 2n), " (2)", false);
check("test3(\"a\", 1n)", () => M.test3("a", 1n), "a (1)", false);
check("test3(\"hello world\", 0n)", () => M.test3("hello world", 0n), "hello world (0)", false);
check("test3(\"\", 13n)", () => M.test3("", 13n), " (13)", false);
check("test3(\"a\", 5n)", () => M.test3("a", 5n), "a (5)", false);
check("test3(\"hello world\", 2n)", () => M.test3("hello world", 2n), "hello world (2)", false);
check("test3(\"héllo, wörld\", 1n)", () => M.test3("héllo, wörld", 1n), "héllo, wörld (1)", false);
check("test3(\"abcabc\", 0n)", () => M.test3("abcabc", 0n), "abcabc (0)", false);
check("test3(\"hello world\", 13n)", () => M.test3("hello world", 13n), "hello world (13)", false);
check("test3(\"héllo, wörld\", 5n)", () => M.test3("héllo, wörld", 5n), "héllo, wörld (5)", false);
check("test3(\"abcabc\", 2n)", () => M.test3("abcabc", 2n), "abcabc (2)", false);
check("test3(\"abcabc\", 13n)", () => M.test3("abcabc", 13n), "abcabc (13)", false);
check("test4", () => M.test4, "total (3, ok)", false);
check("test5", () => M.test5, "h", false);

console.log(`Specialize01-faithful.js: ${passed} passed, ${failed} failed`);
if (failed > 0) process.exit(1);
